UPDATE glossary_terms SET description_ko='브루나이 스카우트연맹의 공식 명칭이다. “Persekutuan”은 연맹 또는 연합, “Pengakap”은 스카우트를 의미하며, ‘브루나이 다루살람 스카우트연맹(Federation of Scouts of Brunei Darussalam)’으로 불린다. 브루나이는 말레이어(Bahasa Melayu)를 국가 공식 언어로 사용하는 말레이 문화권 국가이기 때문에 연맹 명칭도 말레이어 형태로 사용된다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).', updated_at=CURRENT_TIMESTAMP WHERE id=97 AND description_ko IS '브루나이 스카우트연맹의 공식 명칭이다. “Persekutuan”은 연맹 또는 연합, “Pengakap”은 스카우트를 의미하며, ‘브루나이 다루살람 스카우트연맹(Federation of Scouts of Brunei Darussalam)’으로 불린다. 브루나이는 말레이어(Bahasa Melayu)를 국가 공식 언어로 사용하는 말레이 문화권 국가이기 때문에 연맹 명칭도 말레이어 형태로 사용된다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).' AND updated_at IS '2026-10-08 01:50:39';
