UPDATE glossary_terms SET description_ko='인도의 스카우트 연맹으로, 1950년 여러 스카우트 단체의 통합을 통해 설립되었다. 인도에는 다양한 스카우트 단체가 존재하지만, The Bharat Scouts and Guides는 세계스카우트연맹과 세계걸스카우트연맹에 가입한 인도의 대표 스카우트 연맹으로 인정되고 있다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).', updated_at=CURRENT_TIMESTAMP WHERE id=101 AND description_ko IS '인도의 스카우트 연맹으로, 1950년 여러 스카우트 단체의 통합을 통해 설립되었다. 인도에는 다양한 스카우트 단체가 존재하지만, The Bharat Scouts and Guides는 세계스카우트연맹과 세계걸스카우트연맹에 가입한 인도의 대표 스카우트 연맹으로 인정되고 있다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).' AND updated_at IS '2026-10-08 03:11:37';
